def require_fts5_trigram(apps, schema_editor):
    """Fail with a clear message, not "no such module", on an SQLite without FTS5 trigram."""
    import sqlite3

    probe = sqlite3.connect(":memory:")
    try:
        probe.execute("CREATE VIRTUAL TABLE t USING fts5(x, tokenize='trigram')")
    except sqlite3.Error as error:
        raise RuntimeError(
            f"SQLite {sqlite3.sqlite_version} lacks FTS5 with the trigram tokenizer ({error}); "
            "yaradude needs SQLite 3.34 or newer built with FTS5."
        ) from None
    finally:
        probe.close()


